// revenue-conversion-fix.js
// Brainstem directive: paidEvents zero after many runs.
// This module hooks into checkout completion to increment paidEvents.

const fs = require('fs');
const path = require('path');

const REVENUE_FILE = path.join(__dirname, '..', 'data', 'revenue.json');

function loadRevenue() {
  try {
    const raw = fs.readFileSync(REVENUE_FILE, 'utf8');
    return JSON.parse(raw);
  } catch (e) {
    return { paidEvents: 0, conversionRate: 0, leads: 0 };
  }
}

function saveRevenue(data) {
  fs.writeFileSync(REVENUE_FILE, JSON.stringify(data, null, 2));
}

function recordPaidEvent() {
  const data = loadRevenue();
  data.paidEvents = (data.paidEvents || 0) + 1;
  data.conversionRate = data.leads > 0 ? (data.paidEvents / data.leads) : 0;
  saveRevenue(data);
  console.log(`[revenue-conversion-fix] recorded paid event. total: ${data.paidEvents}`);
}

// Hook into checkout success (assumes a global event or module export)
// This is a placeholder; integrate with actual checkout flow.
module.exports = { recordPaidEvent };

